import Foundation
import ChatGPTAccount
import ChatGPTText
import ChatGPTImage
import ChatGPTTextProvider
import LanguageModelCore
import LanguageModelRuntime

// Public README bodies compile but are never invoked: no remote/account/model effects.
func accountReadme() async throws {

let account = try ChatGPTAccountSession(credentialNamespace: "com.example.app")
let authorization = try await account.beginSignIn()
// host가 authorization.authorizationURL을 외부/system browser로 엽니다.
// 기존 localhost callback listener가 redirect를 수신합니다.
let signedInAccount = try await account.completeSignIn(authorization)
let status = try await account.status()
// 명시 취소: try await account.cancelSignIn()
// 명시 로그아웃: try await account.signOut()
  _ = (signedInAccount, status)
}
func textReadme(account: ChatGPTAccountSession, request: ModelRequest) async throws {

// account는 host가 로그인한 공통 ChatGPTAccountSession입니다.
let text = ChatGPTTextSession(account: account)
let models = try await text.models()
let limits = try await text.rateLimits()
let client = try ChatGPTModelClient(text: text)
// request는 호출자가 만든 유효한 ModelRequest입니다.
let turn = try await client.generate(request: request)
  _ = (models, limits, turn)
}
func imageReadme(account: ChatGPTAccountSession, pngData: Data) async throws {

let client = try ChatGPTImageClient(account: account)
let generated = try await client.generate(.init(
  prompt: "투명 배경의 파란 새 한 마리",
  background: .transparent
))
// 사용자가 제공한 실제 PNG bytes를 전달합니다.
let input = ChatGPTImageContent(mimeType: "image/png", data: pngData, filename: "input.png")
let edited = try await client.edit(.init(images: [input], prompt: "새의 색만 초록색으로 바꾼다."))
  _ = (generated, edited)
}
func consume(
  client: ChatGPTModelClient, request: ModelRequest,
  receive: @Sendable (ModelEvent) -> Void
) async throws {
  let invocation = client.invocation(request: request, onStarted: {})
  try await withTaskCancellationHandler {
    let reading: Result<Void, any Error>
    do {
      for try await event in invocation.events { receive(event) }
      reading = .success(())
    } catch {
      invocation.cancel()
      reading = .failure(error)
    }
    // 실패한 receipt를 다시 기다려 성공으로 바꾸지 않는다.
    try await invocation.waitForCompletion()
    try Task.checkCancellation()
    try reading.get()
  } onCancel: {
    invocation.cancel()
  }
}
func providerBinding(account: ChatGPTAccountSession) throws -> ChatGPTProviderConnector {
  try ChatGPTProviderConnector(account: account, policy: .default)
}
enum ConsumerCheck: Error { case mismatch }
@main struct Main {
  static func main() throws {
    let request = ModelRequest(sessionID: "external-consumer", messages: [.init(role: .user, content: "  hello\n")], tools: [])
    let projection = try ModelTextRequest(request, descriptor: .init(id: "example", providerID: "consumer", capabilities: .textOnly))
    guard projection.prompt == "  hello\n" else { throw ConsumerCheck.mismatch }
    var accumulator = ModelTextSnapshotAccumulator(request: request)
    guard try accumulator.receive("e") == ["e"],
      try accumulator.receive("e\u{301}") == ["\u{301}"],
      try accumulator.finish().utf8.elementsEqual("e\u{301}".utf8)
    else { throw ConsumerCheck.mismatch }
    guard ChatGPTRuntime.providerID == "chatgpt.subscription" else { throw ConsumerCheck.mismatch }
    #if !canImport(Security)
    do {
      _ = try ChatGPTAccountSession(credentialNamespace: "consumer.unsupported")
      throw ConsumerCheck.mismatch
    } catch let failure as ChatGPTFailure {
      guard failure.code == .invalidConfiguration else { throw ConsumerCheck.mismatch }
    }
    #endif
    print("PUBLIC_CONSUMER_CORE_AND_UNSUPPORTED_HOST_OK; no live login, image or inference executed")
  }
}

